#!/usr/bin/env bash
set -euo pipefail
root=/var/lib/steam-top-bootstrap/first-deploy;config=/etc/steam-top-bootstrap/trust.json
[[ $(id -u) -eq 0 && $# -eq 0 && -L $root/current ]]||exit 1
inspection=$(mktemp);trap 'rm -f "$inspection"' EXIT;node /opt/steam-top-bootstrap/inspect-first-deploy-chain.mjs "$root/generations" "$root/current" >"$inspection";payload=$(node -p 'require(process.argv[1]).head.payloadPath' "$inspection");allowed=$(node -p 'require(process.argv[1]).productionStateAllowedSigners' "$config");while IFS=$'\t' read -r item sig;do signer=$(node -p 'require(process.argv[1]).signerKeyId' "$item");ssh-keygen -Y verify -q -f "$allowed" -I "$signer" -n steam-top-first-deploy-state -s "$sig" <"$item";done < <(node -e 'for(const g of require(process.argv[1]).generations)console.log(`${g.payloadPath}\t${g.signaturePath}`)' "$inspection")
read -r receipt_digest receipt_nonce live_host live_bootstrap < <(/opt/steam-top-bootstrap/read-install-receipt.sh)
node -e 'const x=require(process.argv[1]);if(x.schemaVersion!==1||x.purpose!=="steam-top-first-deploy-state"||!["pending","db-claimed","consumed"].includes(x.phase)||x.authorizationNonce!==process.argv[2]||x.hostId!==process.argv[3]||x.bootstrapDigest!==process.argv[4]||x.installReceiptDigest!==process.argv[5])process.exit(1);console.log([x.phase,x.authorizationNonce,x.hostId,x.bootstrapDigest,x.installReceiptDigest].join(" "))' "$payload" "$receipt_nonce" "$live_host" "$live_bootstrap" "$receipt_digest"
